trait Shape { fn label(&self) -> &'static str; }
struct Circle;
struct Square;
impl Shape for Circle { fn label(&self) -> &'static str { "circle" } }
impl Shape for Square { fn label(&self) -> &'static str { "square" } }
fn static_label<S: Shape>(shape: &S) -> &'static str { shape.label() }
fn dynamic_label(shape: &dyn Shape) -> &'static str { shape.label() }
fn main() {
    let circle = Circle;
    let square = Square;
    let mixed: [&dyn Shape; 2] = [&circle, &square];
    assert_eq!(static_label(&circle), "circle");
    for shape in mixed { println!("{}", dynamic_label(shape)); }
}
